import {LightningElement} from 'lwc'; export default class Probe extends LightningElement {result='pending';renderedCallback(){if(this.result!=='pending')return;let all=[...this.template.querySelectorAll('lightning-empty-state')];this.result=JSON.stringify(all.map(e=>Object.fromEntries(['title','headingLevel','illustrationName','alternativeText','size'].map(k=>[k,e[k]===undefined?'undefined':e[k]]))));}}